INK=colors.HexColor('#17312F');TEAL=colors.HexColor('#116B63');LIGHT=colors.HexColor('#EAF4F0');GRAY=colors.HexColor('#526361')
styles={
 'title':ParagraphStyle('title',fontName='Arial-Bold',fontSize=21,leading=26,textColor=INK,spaceAfter=14),
 'sub':ParagraphStyle('sub',fontName='Arial-Bold',fontSize=11,leading=15,textColor=TEAL,spaceBefore=8,spaceAfter=6),
 'body':ParagraphStyle('body',fontName='Arial',fontSize=10,leading=14.2,textColor=INK,spaceAfter=8),
 'small':ParagraphStyle('small',fontName='Arial',fontSize=8.6,leading=11.8,textColor=GRAY,spaceAfter=6),
 'cell':ParagraphStyle('cell',fontName='Arial',fontSize=8.7,leading=11.6,textColor=INK),
 'head':ParagraphStyle('head',fontName='Arial-Bold',fontSize=8.7,leading=11.6,textColor=colors.white),
}
story=[]
def clean(text):
 text=str(text)
 text=re.sub(r'(?<=\d)(?=[А-Яа-яЁё₸])',' ',text)
 text=re.sub(r'(?<=[А-Яа-яЁё])(?=\d)',' ',text)
 text=re.sub(r'(?<=[%₸])(?=[А-Яа-яЁё])',' ',text)
 text=re.sub(r'(?<=\d)(?=(?:app_id|client_id|temp-|NEW|CSV|PDF|KEY))',' ',text)
 text=re.sub(r'(?<=,)(?=[А-Яа-яЁёA-Za-z])',' ',text)
 text=re.sub(r'(?<=[А-Яа-яЁё])(?=(?:KB|CSV|PDF|CRM|M1|KEY|NEW|D07|R139))',' ',text)
 text=re.sub(r'(?<=[А-Яа-яЁё])(?=[A-Za-z])',' ',text)
 text=re.sub(r'(?<=[A-Za-z])(?=[А-Яа-яЁё])',' ',text)
 return text
def p(text,sty='body'):story.append(Paragraph(clean(text),styles[sty]))
def sub(text):p(text,'sub')
def page(title,kicker):
 while story and isinstance(story[-1],Spacer):story.pop()
 if story:story.append(PageBreak())
 p(kicker.upper(),'small');p(title,'title')
def table(headers,rows,widths):
 data=[[Paragraph(escape(clean(c)),styles['head']) for c in headers]]+[[Paragraph(escape(clean(c)),styles['cell']) for c in row] for row in rows]
 t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),TEAL),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
 story.extend([t,Spacer(1,10)])

